
  create view "postgres"."dbt"."stg_customers__dbt_tmp" as (
    





with staging as (
    -- Generated by AutomateDV (formerly known as dbtvault)

    

WITH source_data AS (

    SELECT

    id,
    first_name,
    last_name,
    email

    FROM "postgres"."dbt"."source_customers"
),

derived_columns AS (

    SELECT

    id,
    first_name,
    last_name,
    email,
    email AS CUSTOMER_KEY,
    'CSV_CUSTOMERS' AS RECORD_SOURCE

    FROM source_data
),

hashed_columns AS (

    SELECT

    id,
    first_name,
    last_name,
    email,
    CUSTOMER_KEY,
    RECORD_SOURCE,

    DECODE(MD5(NULLIF(UPPER(TRIM(CAST(email AS VARCHAR))), '')), 'hex') AS CUSTOMER_PK,

    DECODE(MD5(CONCAT_WS('||',
        COALESCE(NULLIF(UPPER(TRIM(CAST(first_name AS VARCHAR))), ''), '^^'),
        COALESCE(NULLIF(UPPER(TRIM(CAST(id AS VARCHAR))), ''), '^^'),
        COALESCE(NULLIF(UPPER(TRIM(CAST(last_name AS VARCHAR))), ''), '^^')
    )), 'hex') AS CUSTOMER_HASHDIFF

    FROM derived_columns
),

columns_to_select AS (

    SELECT

    id,
    first_name,
    last_name,
    email,
    CUSTOMER_KEY,
    RECORD_SOURCE,
    CUSTOMER_PK,
    CUSTOMER_HASHDIFF

    FROM hashed_columns
)

SELECT * FROM columns_to_select
)

select *, current_timestamp as LOAD_DATE,
    current_timestamp AS EFFECTIVE_FROM from staging
  );